///////////////////////////////////////////////////////////////////////////////
//
// Module      :  functions.h
// Copyright   :  (c) Andy Arvanitis 2019
// License     :  BSD
//
// Maintainer  :  Andy Arvanitis
// Stability   :  experimental
// Portability :
//
// Runtime function types (for regular functions and lambdas)
//
///////////////////////////////////////////////////////////////////////////////
//
#ifndef purescript_functions_H
#define purescript_functions_H

namespace purescript {
    namespace _template_ {

    template <typename T>
    class fn_t {
    public:
        virtual ~fn_t() {}
        virtual auto operator ()(const T&) const -> T = 0;
    };

    template <typename T, typename U>
    class fn_T : public fn_t<T> {
        U fn;
    public:
        fn_T(U&& f) noexcept : fn(std::move(f)) {}
        auto operator ()(const T& arg) const -> T override {
            return fn(arg);
        }
    };

    template <typename T>
    class eff_fn_t {
    public:
        virtual ~eff_fn_t() {}
        virtual auto operator ()() const -> T = 0;
    };

    template <typename T, typename U>
    class eff_fn_T : public eff_fn_t<T> {
        U fn;
    public:
        eff_fn_T(U&& f) noexcept : fn(std::move(f)) {}
        auto operator ()() const -> T override {
            return fn();
        }
    };

    } // namespace _template_
} // namespace purescript

#endif // purescript_functions_H

recursion.h.text:
///////////////////////////////////////////////////////////////////////////////
//
// Module      :  recursion.h
// Copyright   :  (c) Andy Arvanitis 2019
// License     :  BSD
//
// Maintainer  :  Andy Arvanitis
// Stability   :  experimental
// Portability :
//
// Runtime types to support recursion
//
///////////////////////////////////////////////////////////////////////////////
//
#ifndef purescript_recursion_H
#define purescript_recursion_H

#include <memory>

namespace purescript {

    namespace _template_ {

    template <typename T>
    class weak {
        std::weak_ptr<void> wptr;

        public:
        weak() = delete;
        weak(T& b) : wptr(b.shared) {}

        auto shared() const -> std::shared_ptr<void> {
#if defined(NDEBUG)
            return wptr.lock();
#else
            return static_cast<std::shared_ptr<void>>(wptr);
#endif
        }

    }; // class weak

    template <typename T>
    class recur {
        std::shared_ptr<T> sptr;
        std::shared_ptr<typename T::weak> wptr;

        public:
        recur() : sptr(std::make_shared<T>())
              , wptr(std::make_shared<typename T::weak>(*sptr)) {}

        auto shared() const -> std::shared_ptr<void> {
            return sptr->shared;
        }

        auto operator()() const -> T {
            return (*sptr)();
        }

        auto operator()(const T& arg) const -> T {
            return (*sptr)(arg);
        }

        template <typename U>
        auto operator=(U&& right) -> recur& {
            *sptr = std::forward<U>(right);
            *wptr = *sptr;
            return *this;
        }

        class weak {
            std::shared_ptr<typename T::weak> wptr;
        public:
            weak(const recur& r) : wptr(r.wptr) {}

            auto shared() const -> std::shared_ptr<void> {
                return wptr->shared();
            }

            auto operator()() const -> T {
                return static_cast<T>(*wptr)();
            }

            auto operator()(const T& arg) const -> T {
                return static_cast<T>(*wptr)(arg);
            }
        }; // class recur::weak
    }; // class recur

    } // namespace _template_
} // namespace purescript

#endif // purescript_recursion_H

bench_ffi.cc.text:
#include "purescript.h"
#include <chrono>
#include <iomanip>
#include <sstream>
#include <stdexcept>

namespace {
// Treat the boxed input (including primitive fields) as unknown at every call.
// The runner also compiles separate translation units without LTO.
#if defined(__clang__) || defined(__GNUC__)
__attribute__((noinline))
void opaque_input(purescript::boxed& value) {
    asm volatile("" : "+m"(value) : : "memory");
}
#else
#error "The C++ benchmark requires a compiler supporting the opaque input barrier"
#endif
}

FOREIGN_BEGIN(Bench)
exports["benchNow"] = []() -> boxed {
    using Clock = std::chrono::steady_clock;
    static const auto origin = Clock::now();
    return std::chrono::duration<double, std::micro>(Clock::now() - origin).count();
};
exports["formatNumber"] = [](const boxed& value) -> boxed {
    std::ostringstream text;
    text << std::fixed << std::setprecision(6) << unbox<double>(value);
    return text.str();
};
exports["opaque"] = [](const boxed& value) -> boxed {
    return [value]() -> boxed {
        boxed input = value;
        opaque_input(input);
        return input;
    };
};
exports["measureBatch"] = [](const boxed& count) -> boxed {
    return [count](const boxed& expected) -> boxed {
        return [count, expected](const boxed& act) -> boxed {
            return [count, expected, act]() -> boxed {
                using Clock = std::chrono::steady_clock;
                boxed result = 0;
                const auto start = Clock::now();
                for (int i = 0; i < unbox<int>(count); ++i) {
                    result = act();
                    opaque_input(result);
                }
                const double elapsed = std::chrono::duration<double, std::micro>(Clock::now() - start).count();
                if (unbox<int>(result) != unbox<int>(expected))
                    throw std::runtime_error("Unstable benchmark result");
                return elapsed / unbox<int>(count);
            };
        };
    };
};
FOREIGN_END
